(function(){
 const KEY='nawaf-hq-v3',MODE='real-workforce-v1';
 const get=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}},put=s=>localStorage.setItem(KEY,JSON.stringify(s));
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const now=()=>new Date().toISOString(),name=(s,id)=>id==='nawaf'?'نواف':(s.employees||[]).find(e=>e.id===id)?.name||id;
 function ensure(s){s.discussions=s.discussions||[];if(!s.discussions.find(r=>r.id==='company'))s.discussions.unshift({id:'company',type:'COMPANY',title:'مجلس الشركة',participants:['nawaf','sara','omar','lian','noura'],messages:[]});return s}
 function modal(html){let m=document.querySelector('#modal'),d=document.querySelector('#dialog');if(!m||!d)return;d.innerHTML='<div class="dialog-wide board-dialog">'+html+'</div>';m.classList.add('open');m.onclick=e=>{if(e.target===m)m.classList.remove('open')}}
 function rooms(s){const base=[s.discussions.find(r=>r.id==='company'),...(s.discussions||[]).filter(r=>r.id!=='company')].filter(Boolean);return base}
 function openBoard(roomId='company'){
  let s=ensure(get());if(!s||s.meta?.mode!==MODE)return;let rs=rooms(s),room=rs.find(r=>r.id===roomId)||rs[0];
  const connected=(s.integrations||[]).find(i=>i.id==='ai-model'&&i.status==='CONNECTED');
  const msgs=(room.messages||[]).map(m=>`<article class="board-msg ${m.author==='nawaf'?'ceo':''}"><header><b>${esc(name(s,m.author))}</b><time>${new Date(m.createdAt).toLocaleString('ar-SA',{hour:'2-digit',minute:'2-digit'})}</time></header><p>${esc(m.text)}</p>${links(m,s)}</article>`).join('')||'<div class="board-empty">ما فيه نقاش إلى الآن. أول رسالة منك تبدأ السياق، ولن نخترع ردود موظفين بدون محرك AI متصل أو نتيجة عمل حقيقية.</div>';
  modal(`<div class="board-head"><div><span class="eyebrow">COMPANY DISCUSSIONS</span><h2>${esc(room.title)}</h2><p>نقاشات مرتبطة بالشغل والأدلة، مو رسائل تمثيلية.</p></div><button class="dialog-close" id="board-close">إغلاق</button></div><div class="board-layout"><aside class="board-rooms"><b>الغرف</b>${rs.map(r=>`<button data-room="${esc(r.id)}" class="${r.id===room.id?'active':''}">${esc(r.title)}<small>${(r.messages||[]).length} رسالة</small></button>`).join('')}</aside><main class="board-main"><div class="board-truth ${connected?'connected':'offline'}"><i></i><span>${connected?'محرك AI متصل — يمكن تشغيل مناقشات الموظفين':'محرك AI غير متصل — لن نولّد ردود موظفين وهمية'}</span></div><section class="board-messages">${msgs}</section><form id="board-form"><textarea required placeholder="اكتب للفريق أو ادخل في النقاش..."></textarea><button class="primary">إرسال للمجلس</button></form><div class="board-tools"><button id="board-evidence">استخراج نقاط قابلة للنقاش من النتائج الحقيقية</button><button id="board-command">إنشاء توجيه عمل جديد</button></div></main></div>`);
  document.querySelector('#board-close').onclick=()=>document.querySelector('#modal').classList.remove('open');
  document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>openBoard(b.dataset.room));
  document.querySelector('#board-form').onsubmit=e=>{e.preventDefault();let text=e.target.querySelector('textarea').value.trim();if(!text)return;s=ensure(get());let r=s.discussions.find(x=>x.id===room.id);r.messages.push({id:'msg-'+Date.now(),author:'nawaf',text,createdAt:now(),type:'CEO_MESSAGE',links:{}});s.activities.unshift({id:'audit-'+Date.now(),text:'نواف أرسل رسالة في '+r.title,kind:'REAL',createdAt:now(),links:{discussion:r.id}});put(s);openBoard(r.id)};
  document.querySelector('#board-evidence').onclick=()=>evidence(room.id);
  document.querySelector('#board-command').onclick=()=>{document.querySelector('#modal').classList.remove('open');setTimeout(()=>{const b=[...document.querySelectorAll('button')].find(x=>x.textContent.includes('بسم الله')||x.textContent.includes('أعطِ توجيهًا'));b?.click()},50)};
 }
 function links(m,s){let a=[];if(m.links?.report)a.push('تقرير');if(m.links?.artifact)a.push('مخرج');if(m.links?.task)a.push('مهمة');return a.length?'<footer>مرتبط بـ: '+a.join(' · ')+'</footer>':''}
 function evidence(roomId){let s=ensure(get()),r=s.discussions.find(x=>x.id===roomId);let pid=r?.project;let arts=(s.artifacts||[]).filter(a=>!pid||a.project===pid),reps=(s.reports||[]).filter(a=>!pid||a.project===pid);if(!arts.length&&!reps.length){alert('ما فيه نتائج حقيقية مرتبطة بهذه الغرفة إلى الآن. لن ننشئ نقاشًا وهميًا.');return}let latest=arts.at(-1),rep=reps.at(-1),facts=latest?.findings||[];let text=facts.length?'نقاط مثبتة من آخر مخرج:\n• '+facts.slice(0,4).join('\n• '):'يوجد تقرير حقيقي جاهز للنقاش: '+rep.title;r.messages.push({id:'msg-'+Date.now(),author:latest?.author||rep?.author||'noura',text,createdAt:now(),type:'EVIDENCE_DISCUSSION',links:{artifact:latest?.id,report:rep?.id}});s.activities.unshift({id:'audit-'+Date.now(),text:'أضيفت نقاط نقاش من نتيجة عمل محفوظة',kind:'REAL',createdAt:now(),links:{discussion:r.id,artifact:latest?.id,report:rep?.id}});put(s);openBoard(roomId)}
 function bind(){document.querySelectorAll('button').forEach(b=>{if(b.dataset.boardBound)return;if(b.textContent.includes('مجلس الشركة')){b.dataset.boardBound='1';b.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();openBoard('company')},true)}});let core=document.querySelector('#manager-core');if(core&&!core.dataset.boardBound){core.dataset.boardBound='1';core.addEventListener('dblclick',()=>openBoard('company'))}}
 const mo=new MutationObserver(()=>{clearTimeout(window.__boardBind);window.__boardBind=setTimeout(bind,60)});mo.observe(document.documentElement,{subtree:true,childList:true});document.readyState==='loading'?document.addEventListener('DOMContentLoaded',bind):bind();window.NawafCompanyBoard={open:openBoard};
})();